import React from "react";
import {
    LineChart,
    Line,
    XAxis,
    YAxis,
    Tooltip,
    ResponsiveContainer,
} from "recharts";

const data = [
    { day: "Mon", usage: 400 },
    { day: "Tue", usage: 300 },
    { day: "Wed", usage: 500 },
    { day: "Thu", usage: 200 },
    { day: "Fri", usage: 700 },
    { day: "Sat", usage: 600 },
    { day: "Sun", usage: 800 },
];

function UsageChart() {
    return (
        <ResponsiveContainer width="100%" height={300}>
            <LineChart data={data}>
                <XAxis dataKey="day" stroke="#ccc" />
                <YAxis stroke="#ccc" />
                <Tooltip />
                <Line type="monotone" dataKey="usage" stroke="#3b82f6" />
            </LineChart>
        </ResponsiveContainer>
    );
}

export default UsageChart;
